 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    PlaneGeometry,
    DoubleSide,
    SRGBColorSpace
  } = ctx.THREE;

  const root = new Group();
  root.name = config.id || 'journal-title';
  root.userData.handlers = {};

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const region = config.intent?.visualSpec?.atlasRegion ?? config.atlasRegion ?? {
    atlas: 0,
    x: 0,
    y: 0,
    w: 512,
    h: 320
  };

  const aspect = region.h ? region.w / region.h : 1.6;
  const planeWidth = 2.0;
  const planeHeight = planeWidth / aspect;

  const geometry = new PlaneGeometry(planeWidth, planeHeight, 1, 1);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0,
    side: DoubleSide,
    depthWrite: false
  });

  const sprite = new Mesh(geometry, material);
  sprite.name = 'journal-accent-sprite';
  root.add(sprite);

  function applyAtlasUVs(texW, texH) {
    const uvs = geometry.attributes.uv;
    const u0 = region.x / texW;
    const u1 = (region.x + region.w) / texW;
    const v0 = (texH - (region.y + region.h)) / texH;
    const v1 = (texH - region.y) / texH;
    for (let i = 0; i < uvs.count; i++) {
      const u = uvs.getX(i);
      const v = uvs.getY(i);
      uvs.setXY(i, u0 + u * (u1 - u0), v0 + v * (v1 - v0));
    }
    uvs.needsUpdate = true;
  }

  let texture = null;
  let disposed = false;

  const timelines = [];
  const primitiveCleanups = [];

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        if (disposed) {
          tex.dispose();
          return;
        }
        texture = tex;
        tex.colorSpace = SRGBColorSpace;
        tex.needsUpdate = true;
        material.map = tex;
        material.needsUpdate = true;
        if (tex.image?.width && tex.image?.height) {
          applyAtlasUVs(tex.image.width, tex.image.height);
        }
      })
      .catch(() => {});
  }

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const roleHeights = {
    hero: 0.62,
    headline: 0.34,
    subhead: 0.2,
    body: 0.13,
    caption: 0.09
  };

  const textObjects = [];

  for (const item of items) {
    if (!item?.text) continue;
    const content = String(item.text);
    const role = item.role || 'body';
    const fontSize = item.typography?.fontSize || roleHeights[role] || 0.13;

    const label = ctx.fontAtlas.createText(content, {
      fontSize,
      color: colors.paper,
      align: item.align || 'center'
    });

    label.name = `text-${role}`;
    const targetHeight = roleHeights[role] ?? 0.13;
    if (fontSize > 0) {
      label.scale.setScalar(targetHeight / fontSize);
    }
    label.position.z = 0.02;
    sprite.add(label);
    textObjects.push(label);
  }

  sprite.onBeforeRender = (_renderer, _scene, camera) => {
    sprite.lookAt(camera.position);
  };

  for (const primitive of config.cinematicPrimitives ?? []) {
    if (ctx.primitives?.[primitive.name]) {
      const handle = ctx.primitives[primitive.name](root, primitive.params ?? {});
      if (handle?.timeline) timelines.push(handle.timeline);
      if (handle?.cleanup) primitiveCleanups.push(handle.cleanup);
    }
  }

  const entrance = gsap.timeline();
  timelines.push(entrance);

  root.position.y = 0.3;
  root.scale.setScalar(0.92);

  entrance.to(
    root.position,
    { y: 0, duration: 0.7, ease: 'power3.out' },
    0
  );
  entrance.to(
    root.scale,
    { x: 1, y: 1, z: 1, duration: 0.8, ease: 'power4.out' },
    0
  );
  entrance.to(
    material,
    { opacity: 1, duration: 0.6, ease: 'power2.out' },
    0
  );

  for (const textObj of textObjects) {
    const mats = [];
    textObj.traverse((child) => {
      if (child.isMesh && child.material) {
        child.material.transparent = true;
        child.material.opacity = 0;
        mats.push(child.material);
      }
    });
    if (mats.length) {
      entrance.to(
        mats,
        { opacity: 1, duration: 0.6, ease: 'power2.out' },
        0
      );
    }
  }

  root.userData.cleanup = () => {
    disposed = true;
    timelines.forEach((t) => t.kill());
    primitiveCleanups.forEach((fn) => {
      try {
        fn();
      } catch (e) {}
    });

    if (texture) texture.dispose();
    material.dispose();
    geometry.dispose();

    for (const textObj of textObjects) {
      textObj.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    }

    sprite.onBeforeRender = null;
  };

  return root;
}
